insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('aa1fcdba-10c4-535c-ae31-1a8db98a48bc', 'tancha-classic-24l-school-backpack', 'Tancha Classic 24L School Backpack', 'The bag that survives a full term of Lagos traffic and playground abuse.', 'Built with the producer we buy direct from, so you pay factory price instead of three markups. The base is double-stitched and the straps are anchored through the back panel, not just sewn onto the fabric — that is the difference between a bag that lasts one term and one that lasts three years.', ARRAY['Reinforced double-stitched base — the seam that usually goes first','Padded laptop sleeve fits up to 14"','Water-resistant 600D polyester shell','24 litres: textbooks, lunch box, water bottle, still zips']::text[], 'Tancha', '74afd81d-b64d-5c84-a36f-3e77fcf3c355', 'backpack', 1150000, 2400000, 120, 4.7, 312, 1840, ARRAY['back-to-school','bestseller']::text[], 2, 5, true, true) on conflict (slug) do nothing;
