insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('addf2ba9-fde0-5d6f-8610-679f4fea276b', 'junior-16l-backpack-primary-school', 'Junior 16L Backpack (Primary School)', 'Sized for small shoulders. Priced for a family buying three at once.', 'Made for primary pupils: lighter frame, shorter back panel, and a chest clip so the weight sits where it should. The reflective strip is not decoration — it matters on a 6am walk to the bus stop.', ARRAY['Chest clip keeps the load off small shoulders','Reflective strip on the front panel for early-morning walks','Wipe-clean lining','Buy 3+ and the bulk price applies automatically']::text[], 'Tancha', '74afd81d-b64d-5c84-a36f-3e77fcf3c355', 'backpack', 720000, 1450000, 90, 4.6, 198, 1210, ARRAY['back-to-school','bestseller','bulk-discount']::text[], 2, 5, true, true) on conflict (slug) do nothing;
