insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('f33fcc66-9448-51c5-a301-cd855f87a640', 'trolley-school-bag-with-detachable-backpack', 'Trolley School Bag with Detachable Backpack', 'Wheels for the walk, straps for the stairs.', 'The honest use case: wheel it to the gate, unclip it for the staircase. Most trolley bags fail at the handle joint — this one uses a metal collar instead of moulded plastic.', ARRAY['Backpack detaches from the trolley frame in one clip','Reinforced telescopic handle, rated to 20kg','Rubberised wheels that survive uneven pavement']::text[], 'Roverkid', '74afd81d-b64d-5c84-a36f-3e77fcf3c355', 'sportsbag', 2250000, 3900000, 45, 4.5, 87, 410, ARRAY['back-to-school']::text[], 2, 5, true, true) on conflict (slug) do nothing;
insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('ffabe3d4-a027-567d-ae44-47abdebd9daf', 'canvas-sports-boarding-duffel-45l', 'Canvas Sports & Boarding Duffel 45L', 'Boarding house term kit, one bag.', 'Sized against an actual boarding school packing list, not a marketing spec sheet. The shoe compartment is ventilated and sealed off from the main body.', ARRAY['45L — a full term of kit','Separate ventilated shoe compartment','Detachable padded shoulder strap']::text[], 'Tancha', '74afd81d-b64d-5c84-a36f-3e77fcf3c355', 'sportsbag', 1390000, 2450000, 60, 4.4, 64, 288, ARRAY['back-to-school']::text[], 2, 5, true, true) on conflict (slug) do nothing;
insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('13852a42-6084-5ec8-8726-5d28028a5ea4', 'clear-pvc-exam-pouch-3-pack', 'Clear PVC Exam Pouch (3-Pack)', 'Every exam hall wants a transparent pouch. Here are three.', 'Exam boards insist on clear pouches and the cheap ones split at the zip in week two. These use a heavier gauge PVC and a metal-toothed zip.', ARRAY['WAEC/NECO-compliant transparent design','Heavy-gauge zip that does not split','Three pouches per pack']::text[], 'Tancha', '74afd81d-b64d-5c84-a36f-3e77fcf3c355', 'geometry', 240000, 480000, 200, 4.8, 241, 2100, ARRAY['back-to-school','bestseller']::text[], 2, 5, true, true) on conflict (slug) do nothing;
insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('484d4fd8-2fed-553d-91cf-ba4ec6d0b8c8', 'laptop-backpack-15-6-with-usb-port', 'Laptop Backpack 15.6" with USB Port', 'For the secondary school student who is already coding.', 'A working student bag. The USB pass-through connects to your own power bank in the internal pocket — there is no battery included, and any seller telling you otherwise is selling you a cable.', ARRAY['Fits 15.6" laptops with the charger','External USB pass-through for a power bank','Anti-theft rear pocket']::text[], 'Vantel', '74afd81d-b64d-5c84-a36f-3e77fcf3c355', 'backpack', 1780000, 3200000, 55, 4.6, 129, 520, ARRAY['back-to-school','new']::text[], 2, 5, true, true) on conflict (slug) do nothing;
insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('59fe6fa8-94b5-5bbe-b4f8-4cabae4af7bf', 'drawstring-pe-kit-bag-2-pack', 'Drawstring PE Kit Bag (2-Pack)', 'Sports day, swimming, dusty football boots. Two bags, one price.', 'Drawstring bags fail at the corner eyelets. These are reinforced with a leather patch, which is the entire reason to buy this one over the ₦900 version.', ARRAY['Rip-resistant nylon','Reinforced corner eyelets — where drawstring bags always tear','Machine washable']::text[], 'Tancha', '74afd81d-b64d-5c84-a36f-3e77fcf3c355', 'sportsbag', 320000, 650000, 150, 4.3, 156, 940, ARRAY['back-to-school']::text[], 2, 5, true, true) on conflict (slug) do nothing;
insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('fffbe70b-b034-5e07-91cd-48cbd93d44ef', 'insulated-bag-bottle-combo-set', 'Insulated Bag & Bottle Combo Set', 'Lunch bag plus 750ml flask. Bought together, priced together.', 'The combo exists because parents buy both anyway and paying twice for delivery is silly. The flask is stainless steel, not lined plastic.', ARRAY['Keeps a hot meal warm to 1pm','Matching 750ml stainless flask included','Leak-tested seal']::text[], 'Tancha', '74afd81d-b64d-5c84-a36f-3e77fcf3c355', 'lunchbox', 890000, 1700000, 80, 4.7, 203, 870, ARRAY['back-to-school','bestseller']::text[], 2, 5, true, true) on conflict (slug) do nothing;
insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('7194bb8b-5c0f-5ed1-8f40-9ca877d2e3dd', 'a4-hardcover-exercise-books-10-pack-80-leaves', 'A4 Hardcover Exercise Books — 10 Pack (80 leaves)', 'A full term of writing, sorted in one order.', 'Straight from the mill. 70gsm paper is the line between a book you can write on both sides of and one you cannot — most ₦250 exercise books are 55gsm.', ARRAY['80 leaves each, 70gsm — ink does not bleed through','Hard cover survives the bottom of a bag','Margin ruled to school standard']::text[], 'Tancha', '358c2c9c-4aba-5fce-a1e6-2dd5794a1f13', 'notebook', 540000, 1100000, 400, 4.8, 428, 3600, ARRAY['back-to-school','bestseller','bulk-discount']::text[], 2, 5, true, true) on conflict (slug) do nothing;
insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('9b1ed685-de4b-5756-b409-fdd90a58bbd7', 'complete-stationery-starter-kit-32-pieces', 'Complete Stationery Starter Kit (32 pieces)', 'The whole school list in one box. Nothing missing on day one.', 'Assembled from an actual school requirement list rather than whatever the factory had spare. If your school asks for something not in this kit, tell our chat and we will add it to the next batch.', ARRAY['32 pieces: pens, pencils, ruler, eraser, sharpener, crayons, geometry set','Checked against the standard Nigerian school list','Comes in a reusable zip case']::text[], 'Tancha', '358c2c9c-4aba-5fce-a1e6-2dd5794a1f13', 'pens', 690000, 1550000, 250, 4.9, 517, 4200, ARRAY['back-to-school','bestseller']::text[], 2, 5, true, true) on conflict (slug) do nothing;
insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('b2521705-65ca-514a-b742-892c41dc68c3', 'bic-ballpoint-pens-box-of-50-blue', 'Bic Ballpoint Pens — Box of 50 (Blue)', 'Fifty pens. They will still lose them, but not for a while.', 'Counterfeit Bic is everywhere in the open market. Ours comes through the authorised distributor with the batch codes intact.', ARRAY['Genuine Bic — sourced through the authorised distributor','Box of 50, blue','Also available in black and red']::text[], 'Bic', '358c2c9c-4aba-5fce-a1e6-2dd5794a1f13', 'pens', 420000, 780000, 180, 4.7, 289, 2400, ARRAY['back-to-school','bulk-discount']::text[], 2, 5, true, true) on conflict (slug) do nothing;
insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('dd97b457-09aa-5e11-9f09-775a2c455f7e', 'mathematical-set-with-compass-protractor', 'Mathematical Set with Compass & Protractor', 'The one item every maths teacher checks for in week one.', 'The compass is metal with a proper tension screw. Plastic compasses drift mid-circle and every student who has used one knows it.', ARRAY['Metal compass that holds its angle','Set squares, protractor, ruler, dividers','Tin case, not cardboard']::text[], 'Oxford', '358c2c9c-4aba-5fce-a1e6-2dd5794a1f13', 'geometry', 290000, 550000, 300, 4.6, 334, 2900, ARRAY['back-to-school','bestseller']::text[], 2, 5, true, true) on conflict (slug) do nothing;
insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('e1df65bc-cde1-514b-8941-22f3d04c274c', 'jumbo-wax-crayons-24-colours-3-boxes', 'Jumbo Wax Crayons — 24 Colours (3 Boxes)', 'Nursery and primary art, three terms covered.', 'Jumbo barrels because thin crayons snap in a five-year-old grip and then you buy again in October.', ARRAY['Non-toxic, EN71 tested','Jumbo barrel — easier for small hands, harder to snap','24 colours × 3 boxes']::text[], 'Tancha', '358c2c9c-4aba-5fce-a1e6-2dd5794a1f13', 'crayons', 360000, 720000, 220, 4.5, 176, 1150, ARRAY['back-to-school']::text[], 2, 5, true, true) on conflict (slug) do nothing;
insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('de6ad028-0e58-5077-8252-e3fe4d905114', 'a4-ring-binder-files-with-dividers-5-pack', 'A4 Ring Binder Files with Dividers (5-Pack)', 'Secondary school notes that survive to revision season.', 'Ring binders live or die on the mechanism. These have a sprung metal ring that closes flush — the cheap ones misalign and shred your pages.', ARRAY['2-ring mechanism with a proper spring','Five subject dividers per file','Spine label window']::text[], 'Vantel', '358c2c9c-4aba-5fce-a1e6-2dd5794a1f13', 'notebook', 580000, 1050000, 110, 4.4, 92, 480, ARRAY['back-to-school']::text[], 2, 5, true, true) on conflict (slug) do nothing;
insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('3238b370-85bf-512e-9fd8-03ab92d40c46', 'graph-squared-notebooks-6-pack', 'Graph & Squared Notebooks — 6 Pack', 'For maths, physics, and technical drawing.', 'Printed on a calibrated grid, which matters more than it sounds — off-scale graph paper costs marks in technical drawing.', ARRAY['2mm and 5mm grid options','60 leaves each','Perforated for submission']::text[], 'Tancha', '358c2c9c-4aba-5fce-a1e6-2dd5794a1f13', 'notebook', 390000, 760000, 160, 4.6, 118, 690, ARRAY['back-to-school']::text[], 2, 5, true, true) on conflict (slug) do nothing;
insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('fdd6903e-d540-5401-9f5e-16a322379d9b', 'hb-pencils-with-erasers-40-pack', 'HB Pencils with Erasers — 40 Pack', 'The consumable that runs out first.', 'Bonded lead means the core is glued along the full length of the barrel, so it does not shatter inside the pencil when dropped.', ARRAY['Break-resistant bonded lead','Erasers that lift graphite instead of smearing it','Pre-sharpened']::text[], 'Staedtler', '358c2c9c-4aba-5fce-a1e6-2dd5794a1f13', 'pens', 480000, 920000, 190, 4.7, 205, 1680, ARRAY['back-to-school','bulk-discount']::text[], 2, 5, true, true) on conflict (slug) do nothing;
insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('ec353c35-3cc8-55b6-bf0a-c75448d6c3b9', 'textbook-cover-rolls-name-labels-bundle', 'Textbook Cover Rolls & Name Labels Bundle', 'Sunday-night book covering, finished in an hour.', 'The bubble-release backing is the whole point. Ordinary covering film traps air and you end up peeling it off in frustration.', ARRAY['5 metres of clear adhesive film','120 waterproof name labels','Bubble-release backing']::text[], 'Tancha', '358c2c9c-4aba-5fce-a1e6-2dd5794a1f13', 'notebook', 270000, 540000, 140, 4.3, 88, 610, ARRAY['back-to-school']::text[], 2, 5, true, true) on conflict (slug) do nothing;
insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('23df3d08-951b-5391-b609-d0c50ae81487', 'casio-fx-991ex-scientific-calculator', 'Casio fx-991EX Scientific Calculator', 'WAEC, JAMB, and university engineering. One calculator, five years.', 'The Nigerian market is flooded with fx-991 clones that fail on matrix operations. Ours are sourced through the regional distributor and carry the hologram. Scratch it and check the code on Casio’s site if you like — we would rather you did.', ARRAY['Genuine Casio with the holographic authenticity sticker','552 functions, natural textbook display','Solar plus battery — it will not die mid-exam']::text[], 'Casio', '366ee5ae-343e-5044-9b2f-fdc9a2cf54e0', 'calculator', 1650000, 2700000, 85, 4.9, 462, 2750, ARRAY['back-to-school','bestseller','official-store']::text[], 2, 5, true, true) on conflict (slug) do nothing;
insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('d0cb7a81-37b7-596a-bf57-949faceacd33', 'casio-fx-82ms-scientific-calculator', 'Casio fx-82MS Scientific Calculator', 'The school-approved workhorse at the price it should be.', 'If the school list says "scientific calculator" without naming a model, this is the one they mean.', ARRAY['240 functions — covers the full secondary syllabus','Two-line display','Genuine, distributor-sourced']::text[], 'Casio', '366ee5ae-343e-5044-9b2f-fdc9a2cf54e0', 'calculator', 890000, 1550000, 140, 4.7, 388, 3100, ARRAY['back-to-school','bestseller']::text[], 2, 5, true, true) on conflict (slug) do nothing;
