insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('38077b89-d47e-5ab1-bfc1-ec4b7c7a4935', 'rechargeable-led-study-lamp-with-power-bank', 'Rechargeable LED Study Lamp with Power Bank', 'Built for the study session that outlives the light.', 'A study lamp that assumes the light will go. Fourteen hours on low, three brightness levels, and a USB-A port so it charges a phone when it is not lighting a textbook. Flicker-free driver — that is what stops the headache after two hours of reading.', ARRAY['6000mAh — up to 14 hours on the low setting','Doubles as a phone power bank via USB-A','Three colour temperatures, flicker-free','Charges fully in 4 hours']::text[], 'Tancha', '366ee5ae-343e-5044-9b2f-fdc9a2cf54e0', 'lamp', 1250000, 2400000, 95, 4.8, 341, 1920, ARRAY['back-to-school','bestseller']::text[], 2, 5, true, true) on conflict (slug) do nothing;
insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('146a402d-7896-5136-b10c-b91f1b4a6ad8', 'usb-rechargeable-desk-fan-lamp-combo', 'USB Rechargeable Desk Fan & Lamp Combo', 'Two things every Nigerian study desk needs, on one charge.', 'Brushless motor means it is quiet enough to sit beside while reading. Clamps to the desk edge instead of eating your workspace.', ARRAY['Silent brushless motor','4000mAh battery','Clamp mount frees the desk surface']::text[], 'Vantel', '366ee5ae-343e-5044-9b2f-fdc9a2cf54e0', 'lamp', 980000, 1850000, 70, 4.5, 147, 780, ARRAY['back-to-school']::text[], 2, 5, true, true) on conflict (slug) do nothing;
insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('0e30f908-de5e-516f-bedc-e64198cc2076', 'wired-headset-with-mic-for-online-class', 'Wired Headset with Mic for Online Class', 'Cheap enough to replace, good enough that the teacher hears them.', 'Wired on purpose. There is no pairing drama at 8am and no battery to be flat when the class starts.', ARRAY['3.5mm jack plus USB-C adapter in the box','Boom mic with inline mute','Padded over-ear cups']::text[], 'Tancha', '366ee5ae-343e-5044-9b2f-fdc9a2cf54e0', 'earbuds', 540000, 1100000, 130, 4.3, 164, 990, ARRAY['back-to-school']::text[], 2, 5, true, true) on conflict (slug) do nothing;
insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('38ccb7ce-e253-5e51-9512-2ff786328191', 'a4-digital-writing-tablet-lcd-notepad', 'A4 Digital Writing Tablet (LCD Notepad)', 'Rough work without the paper bill.', 'For working out maths, not for storing it. One button clears the screen and the lock switch stops an accidental wipe mid-question.', ARRAY['A4 pressure-sensitive LCD','One-button erase, lock switch to save a page','Coin battery lasts about a year']::text[], 'Vantel', '366ee5ae-343e-5044-9b2f-fdc9a2cf54e0', 'tablet', 760000, 1400000, 88, 4.4, 103, 540, ARRAY['back-to-school','new']::text[], 2, 5, true, true) on conflict (slug) do nothing;
insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('b4a5060a-4fa8-566e-9f85-9cc788fc16df', '4-port-fast-charger-with-surge-protection', '4-Port Fast Charger with Surge Protection', 'One socket, four devices, no fried chargers.', 'The surge protection is not a marketing line — an unstable grid kills more chargers than age does. This one cuts the circuit on a spike.', ARRAY['65W total across 4 ports (2× USB-C PD, 2× USB-A)','Built-in surge and over-voltage protection','NEPA-proof: cuts out on a spike instead of passing it on']::text[], 'Vantel', '366ee5ae-343e-5044-9b2f-fdc9a2cf54e0', 'powerbank', 820000, 1500000, 105, 4.6, 188, 1120, ARRAY['back-to-school']::text[], 2, 5, true, true) on conflict (slug) do nothing;
insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('0f2a5767-faac-5047-bb65-2f80bc9a28b2', 'tancha-buds-pro-wireless-earbuds-anc', 'Tancha Buds Pro — Wireless Earbuds ANC', 'Noise cancelling that actually mutes a generator.', 'Tested against the two sounds that ruin study time in Nigeria: a generator and traffic. Hybrid ANC handles the low-frequency drone; passive seal handles the rest.', ARRAY['Hybrid ANC, ~32dB reduction','8 hours per bud, 32 with the case','Bluetooth 5.3, dual device pairing','IPX5 — survives a downpour on the walk home']::text[], 'Tancha', '64cdd6b1-03b9-5483-ab1f-5182bb4fcab9', 'earbuds', 1890000, 4200000, 65, 4.6, 274, 1340, ARRAY['back-to-school','bestseller','new']::text[], 2, 5, true, true) on conflict (slug) do nothing;
