insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('81b9aa55-8e33-525b-9610-466b0c612443', '20-000mah-power-bank-with-digital-display', '20,000mAh Power Bank with Digital Display', 'Four phone charges. Two days of light off-grid.', 'Capacity fraud is the norm in this category — a "20,000mAh" bank that delivers 9,000 is standard in the open market. We test a sample from every batch and publish the number. This one measures 19,400mAh usable.', ARRAY['True 20,000mAh — independently capacity-tested per batch','22.5W fast charge, USB-C in/out','Digital percentage readout, not four vague dots','Charges three devices at once']::text[], 'Vantel', '64cdd6b1-03b9-5483-ab1f-5182bb4fcab9', 'powerbank', 2150000, 3800000, 78, 4.7, 396, 2050, ARRAY['back-to-school','bestseller']::text[], 2, 5, true, true) on conflict (slug) do nothing;
insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('df634266-0950-5097-8b6a-936d2e1cccf7', '10-000mah-slim-power-bank', '10,000mAh Slim Power Bank', 'Pocket-sized insurance for the school run.', 'The one that actually gets carried. Anything thicker stays on the desk at home.', ARRAY['14mm thin — fits a blazer pocket','18W PD fast charge','Batch capacity-tested']::text[], 'Vantel', '64cdd6b1-03b9-5483-ab1f-5182bb4fcab9', 'powerbank', 1280000, 2200000, 120, 4.5, 221, 1420, ARRAY['back-to-school']::text[], 2, 5, true, true) on conflict (slug) do nothing;
insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('c6fd7f71-610c-5a5b-9e68-54e8ab275a2e', 'bluetooth-speaker-with-fm-torch', 'Bluetooth Speaker with FM & Torch', 'Music, radio, and a torch for when the light goes.', 'Designed around blackouts rather than pool parties. FM works without data, the torch works without a phone.', ARRAY['12 hours playback','FM radio and microSD slot','Built-in torch, IPX6 water resistance']::text[], 'Tancha', '64cdd6b1-03b9-5483-ab1f-5182bb4fcab9', 'earbuds', 1450000, 2700000, 58, 4.4, 132, 620, ARRAY['back-to-school']::text[], 2, 5, true, true) on conflict (slug) do nothing;
insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('1b4cda3a-72a8-5adc-ba06-fec32ab1bb3f', 'universal-fast-charging-cable-set-3-pack', 'Universal Fast Charging Cable Set (3-Pack)', 'USB-C, Lightning, Micro-USB. Whatever is in the house.', 'Braided sheath and reinforced strain relief at the connector, which is the exact place every cable dies.', ARRAY['Braided nylon, 10,000-bend rated','1.5m each — reaches from the socket to the bed','60W rated']::text[], 'Vantel', '64cdd6b1-03b9-5483-ab1f-5182bb4fcab9', 'powerbank', 490000, 950000, 210, 4.5, 267, 1880, ARRAY['back-to-school']::text[], 2, 5, true, true) on conflict (slug) do nothing;
insert into products (id, slug, name, hook, description, bullets, brand, category_id, image_key, price_kobo, compare_at_kobo, stock, rating, review_count, units_sold, tags, delivery_days_min, delivery_days_max, pay_on_delivery, active) values ('3f099366-194d-5799-88d3-463844e59df1', 'over-ear-study-headphones-wired', 'Over-Ear Study Headphones (Wired)', 'Closed-back isolation for a noisy house.', 'Passive isolation over active cancelling: no battery, no hiss, and it works the day it arrives and the day it is three years old.', ARRAY['Closed-back, memory-foam cups','Detachable cable','Folds flat into the supplied pouch']::text[], 'Tancha', '64cdd6b1-03b9-5483-ab1f-5182bb4fcab9', 'earbuds', 1120000, 2100000, 62, 4.5, 118, 470, ARRAY['back-to-school']::text[], 2, 5, true, true) on conflict (slug) do nothing;
